const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();

if (callerRole !== 'ADMIN') {
  return [{
    json: {
      valid: false,
      statusCode: 403,
      error: "Forbidden: Administrator access required to manage employees."
    }
  }];
}

const webhookBody = $('Webhook - POST /admin-employees').first().json.body || {};
const action = (webhookBody.action || 'LIST').toUpperCase().trim();

return [{
  json: {
    valid: true,
    callerId,
    callerRole,
    action,
    body: webhookBody
  }
}];

const prevAction = $('Code - Enforce Admin & Parse Action').first().json.action || 'LIST';
const items = $input.all().map(i => i.json);

if (prevAction === 'CREATE') {
  const emp = items[0] || {};
  return [{
    json: {
      success: true,
      statusCode: 201,
      message: "Employee created successfully with full credentials and seeded leave entitlements.",
      employee: emp
    }
  }];
} else if (prevAction === 'UPDATE') {
  const emp = items[0] || {};
  return [{
    json: {
      success: true,
      statusCode: 200,
      message: "Employee details updated successfully.",
      employee: emp
    }
  }];
} else {
  return [{
    json: {
      success: true,
      statusCode: 200,
      total: items.length,
      employees: items
    }
  }];
}

